export function translateCustomerText(value: string, locale: CustomerLocale): string {
  if (locale !== "en") return value;
  const key = value.replace(/\s+/g, " ").trim();
  const translated = copy[key];
  if (translated !== undefined) return translated;
  // These patterns are controlled presentation templates, not financial facts.
  const suffix = /^尾号 (.+)$/.exec(key);
  if (suffix) return `ending ${suffix[1]}`;
  const wait = /^(\d+)秒后可查回$/.exec(key);
  if (wait) return `Retrieve in ${wait[1]}s`;
  const progress = /^(\d+)\s*\/\s*(\d+)\s*已完成$/.exec(key);
  if (progress) return `${progress[1]} / ${progress[2]} completed`;
  const itemCount = /^(\d+)\s*项$/.exec(key);
  if (itemCount) return `${itemCount[1]} items`;
  return value;
}
export function localizeFinancialValue(value: string, locale: CustomerLocale): string {
  if (locale !== "en") return value;
  return translateCustomerText(value, locale).replace(/ 人民币$/, " CNY").replace(/ 美元$/, " USD");
}

// The transport only reads the current UI language when preparing a new GET.
// Persisted financial/message request bodies are never translated or mutated.
let transportLocale: CustomerLocale = "zh-CN";
let explicitTransportLanguage = false;
export const getCustomerLocale = () => transportLocale;
export const getCustomerRequestLanguage = () => explicitTransportLanguage ? transportLocale : undefined;
export const setTransportLocale = (locale: CustomerLocale, explicit = true) => { transportLocale = locale; explicitTransportLanguage = explicit; };
export const customerUiText = (value: string) => translateCustomerText(value, getCustomerLocale());
